#include "primitive2d_database89.h"
#include <stdio.h>
typedef struct S { unsigned int commands; int bad; } S;
static int sink(void *u,const P2D89_Command *c){S *s;s=(S*)u;if(c==0){s->bad=1;return 0;}if(c->opcode<P2D89_OP_POINT||c->opcode>P2D89_OP_CLOSE){s->bad=1;return 0;}s->commands++;return 1;}
int main(void){unsigned int i;S s;P2D89_Provider p;const P2D89_ShapeInfo *info;s.commands=0U;s.bad=0;p.emit=sink;p.user=&s;if(p2d89_shape_count()!=P2D89_SHAPE_COUNT){puts("count mismatch");return 1;}for(i=0U;i<p2d89_shape_count();++i){info=p2d89_shape_at(i);if(info==0){printf("missing info %u\n",i);return 2;}if(p2d89_find_shape(info->name)!=(P2D89_ShapeId)info->id){printf("lookup fail %s\n",info->name);return 3;}if(!p2d89_emit_shape((P2D89_ShapeId)info->id,&p)){printf("emit fail %s\n",info->name);return 4;}}if(p2d89_find_shape("estrella_15_picos")!=P2D89_SHAPE_STAR_15)return 5;if(p2d89_find_shape("pentagrama_poligonal")!=P2D89_SHAPE_STAR_POLYGON_5_2)return 10;if(p2d89_find_shape("pin_mapa")!=P2D89_SHAPE_MAP_PIN)return 11;if(!p2d89_emit_regular_polygon(37U,0U,&p))return 6;if(!p2d89_emit_star(17U,7000,49152U,&p))return 7;if(!p2d89_emit_spiral(1024U,64U,&p))return 8;if(!p2d89_emit_star_polygon(17U,5U,49152U,&p))return 12;if(p2d89_find_shape("diagrama_decision")!=P2D89_SHAPE_FLOWCHART_DECISION)return 13;if(p2d89_find_shape("casilla_marcada")!=P2D89_SHAPE_WIDGET_CHECKBOX_CHECKED)return 14;if(s.bad)return 9;printf("PASS shapes=%u submodules=%u commands=%u\n",p2d89_shape_count(),p2d89_submodule_count(),s.commands);return 0;}
